import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`ai-workflow-builder`,heroTitle:`Build AI workflows in minutes`,heroSubtitle:`Perplexity Computer turns your workflow brief into a practical AI workflow with steps, triggers, data handoffs, QA checks, and tool connections.`,inputUrlCta:`Build my workflow`,inputUrlPlaceholder:`Paste a workflow brief, company URL, or doc`,inputUrlPrefill:`Go to {url} and build an AI workflow. (1) Analyze the workflow goal, inputs, outputs, tools, constraints, handoffs, and success criteria. (2) Break the workflow into steps, decisions, data transformations, review points, and exception paths. (3) Recommend where AI agents, automations, human approvals, and monitoring should fit. (4) Define triggers, prompts, tool connections, QA checks, and escalation rules. (5) Deliver a build-ready AI workflow spec with implementation steps and operating notes.`,heroOverlaySteps:[`Analyzing the workflow goal, inputs, outputs, tools, and constraints`,`Breaking work into steps, decisions, handoffs, and exception paths`,`Placing AI agents, approvals, monitoring, and tool connections`,`Build-ready workflow spec with QA checks and operating notes, ready to use`],generatingSteps:[`Reading {url} to understand the workflow goal, tools, and constraints`,`Designing an agent to map steps, decisions, data handoffs, and exceptions`,`Configuring AI tasks, human approvals, QA checks, and escalation rules`,`Packaging the workflow into a build-ready implementation spec`],featureSectionTitle:`From process idea to build-ready AI workflow`,featureCardTitles:[`Connects to your workflow tools`,`Outputs you can build`],featureCardDescriptions:[`Computer breaks workflow design into focused tasks, spins up specialized agents, and matches each task to the AI model that fits it best.`,`SOPs, project boards, docs, spreadsheets, Slack, and app workflows can stay connected so the spec reflects how work really moves.`,`Step maps. Trigger definitions. Prompts. QA checks. Escalation paths. Computer gives you an AI workflow spec ready for implementation.`],capabilitySectionTitle:`Your AI workflow architect, on demand`,capabilitySectionSubtitle:`Share the process, step away, and come back to a workflow your team can build.`,capabilityCards:[{title:`Workflow Design`,description:`Computer can turn goals, inputs, tools, and constraints into a clear step-by-step workflow map.`},{title:`Agent Task Planning`,description:`Computer can identify which steps should be handled by AI agents, automation rules, human approvals, or monitoring.`},{title:`QA and Escalation`,description:`Computer can define review checkpoints, failure paths, escalation rules, and quality checks before work ships.`},{title:`Connect Your Tools`,description:`Computer can organize workflow specs across SOPs, docs, spreadsheets, project boards, Slack, and app workflows.`},{title:`Prompt and Trigger Specs`,description:`Computer can draft prompts, trigger logic, data handoffs, and output formats for each workflow step.`},{title:`Operating Notes`,description:`Computer can document owners, metrics, maintenance routines, and iteration ideas so the workflow keeps improving.`}]});export{t as default};
